WITH s, max(c.version) AS cur_ver
MATCH (s)-[c2:CONTAINS]->(p2:Part)
WHERE c2.version = cur_ver AND c2.is_spare = false
WITH s, collect(p2.part_num) AS direct_part_nums
MATCH (s)-[e:EXPLODES]->(item:Part)
WHERE e.is_current = true AND e.is_spare = false
