// So, Direct Contribution = Sum of qty from direct CONTAINS edges (current version, non-spare).
// Total Contribution = Sum of qty from EXPLODES edges (current, non-spare).
// Nested Contribution = Total - Direct.
// Percentage = (Nested / Total) * 100.

MATCH (s:Set {set_num: '71837-1'})
// Get current version
MATCH (s)-[c:CONTAINS]->(:Part)
WITH s, max(c.version) AS cur_ver
// Get direct part quantities
MATCH (s)-[c2:CONTAINS]->(p:Part)
WHERE c2.version = cur_ver AND c2.is_spare = false
WITH s, sum(c2.qty) AS direct_qty
// Get total part quantities from EXPLODES
MATCH (s)-[e:EXPLODES]->(item:Part)
WHERE e.is_current = true AND e.is_spare = false
WITH s, direct_qty, sum(e.qty) AS total_qty
RETURN round((total_qty - direct_qty) * 100.0 / total_qty, 2) AS percentage
